import{_ as e,o as t,c as r,a5 as n}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"HJ100 等差数列","description":"描述 等差数列 2，5，8，11，14。。。。 （从 2 开始的 3 为公差的等差数列） 输出求等差数列前n项和 数据范围： 输入描述： 输入一个正整数n。 输出描述： 输出一个相加后的整数。 示例1 输入： 2 复制 输出： 7 复制 说明： 2+5 7 示例2 输入： 275。","frontmatter":{"title":"HJ100 等差数列","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 等差数列 2，5，8，11，14。。。。 （从 2 开始的 3 为公差的等差数列） 输出求等差数列前n项和 数据范围： 输入描述： 输入一个正整数n。 输出描述： 输出一个相加后的整数。 示例1 输入： 2 复制 输出： 7 复制 说明： 2+5 7 示例2 输入： 275。","sidebarWeight":51,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/HJ100 等差数列.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ100 等差数列.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ100 等差数列.md"}'),o={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ100 等差数列.md"};function i(s,a,h,l,d,p){return t(),r("div",null,[...a[0]||(a[0]=[n('<div><h1 id="hj100-等差数列" tabindex="-1">HJ100 等差数列 <a class="header-anchor" href="#hj100-等差数列" aria-label="Permalink to &quot;HJ100 等差数列&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ100 等差数列”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 <strong>描述</strong> 等差数列 2，5，8，11，14。。。。 （从 2 开始的 3 为公差的等差数列） 输出求等差数列前n项和 数据范围：</p></blockquote><p><strong>输入描述：</strong> 输入一个正整数n。 <strong>输出描述：</strong> 输出一个相加后的整数。 <strong>示例1</strong> 输入： 2 ==复制== 输出： 7 ==复制== 说明： 2+5=7 <strong>示例2</strong> 输入： 275 ==复制== 输出： 113575 ==复制== 说明： 2+5+...+821+824=113575</p><p>求等差数列前n项和的公式是：</p><h1 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h1><p>n = int(input())</p><h1 id="计算前n项和" tabindex="-1">计算前n项和 <a class="header-anchor" href="#计算前n项和" aria-label="Permalink to &quot;计算前n项和&quot;">​</a></h1><p>Sn = n * (3 * n + 1) // 2</p><h1 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h1><p>print(Sn)</p><h1 id="输入-1" tabindex="-1">输入 <a class="header-anchor" href="#输入-1" aria-label="Permalink to &quot;输入&quot;">​</a></h1><p>n = int(input())</p><h1 id="初始化等差数列的首项" tabindex="-1">初始化等差数列的首项 <a class="header-anchor" href="#初始化等差数列的首项" aria-label="Permalink to &quot;初始化等差数列的首项&quot;">​</a></h1><p>first_term = 2</p><h1 id="初始化等差" tabindex="-1">初始化等差 <a class="header-anchor" href="#初始化等差" aria-label="Permalink to &quot;初始化等差&quot;">​</a></h1><p>difference = 3</p><h1 id="初始化和为0" tabindex="-1">初始化和为0 <a class="header-anchor" href="#初始化和为0" aria-label="Permalink to &quot;初始化和为0&quot;">​</a></h1><p>sum = 0</p><h1 id="通过循环累加每一项" tabindex="-1">通过循环累加每一项 <a class="header-anchor" href="#通过循环累加每一项" aria-label="Permalink to &quot;通过循环累加每一项&quot;">​</a></h1><p>for i in range(n):</p><h1 id="计算当前项" tabindex="-1">计算当前项 <a class="header-anchor" href="#计算当前项" aria-label="Permalink to &quot;计算当前项&quot;">​</a></h1><p>current_term = first_term + i * difference</p><h1 id="累加到和中" tabindex="-1">累加到和中 <a class="header-anchor" href="#累加到和中" aria-label="Permalink to &quot;累加到和中&quot;">​</a></h1><p>sum += current_term</p><h1 id="输出和" tabindex="-1">输出和 <a class="header-anchor" href="#输出和" aria-label="Permalink to &quot;输出和&quot;">​</a></h1><p>print(sum)</p></div>',1)])])}const f=e(o,[["render",i]]);export{u as __pageData,f as default};
